### longer wins
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 1, "source": 0, "length": 10}]}
  -> : {"events":[{"type":"match","flow":0,"rule":1,"start":0,"end":1},{"type":"decision","flow":0,"class":10,"reason":"key","at":1,"time":1,"rule":1}]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 2, "source": 0, "length": 10}]}
  -> : {"events":[{"type":"match","flow":0,"rule":1,"start":1,"end":2},{"type":"match","flow":0,"rule":2,"start":0,"end":2}]}
  req: {"op": "close", "flow": 0, "time": 3}
  -> : {"events":[{"type":"closed","flow":0,"packets":2,"matches":3,"class":10,"reason":"key","rule":1}]}
### smaller id wins
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 1, "source": 0, "length": 10}]}
  -> : {"events":[{"type":"match","flow":0,"rule":3,"start":0,"end":1},{"type":"match","flow":0,"rule":9,"start":0,"end":1},{"type":"decision","flow":0,"class":11,"reason":"key","at":1,"time":1,"rule":3}]}
  req: {"op": "close", "flow": 0, "time": 3}
  -> : {"events":[{"type":"closed","flow":0,"packets":1,"matches":2,"class":11,"reason":"key","rule":3}]}
### match after decision
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 1, "source": 0, "length": 50}]}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 2, "source": 0, "length": 10}]}
  -> : {"events":[{"type":"match","flow":0,"rule":1,"start":1,"end":2},{"type":"decision","flow":0,"class":10,"reason":"key","at":2,"time":2,"rule":1}]}
  req: {"op": "close", "flow": 0, "time": 9}
  -> : {"events":[{"type":"closed","flow":0,"packets":2,"matches":1,"class":10,"reason":"key","rule":1}]}
### idle boundary
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "tick", "time": 5}
  -> : {"events":[]}
  req: {"op": "tick", "time": 6}
  -> : {"events":[{"type":"decision","flow":0,"class":7,"reason":"idle","at":0,"time":6,"rule":null}]}
  req: {"op": "close", "flow": 0, "time": 6}
  -> : {"events":[{"type":"closed","flow":0,"packets":0,"matches":0,"class":7,"reason":"idle","rule":null}]}
### padded fallback
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 1, "source": 0, "length": 10}]}
  -> : {"events":[]}
  req: {"op": "close", "flow": 0, "time": 2}
  -> : {"events":[{"type":"decision","flow":0,"class":2,"reason":"end","at":1,"time":2,"rule":null},{"type":"closed","flow":0,"packets":1,"matches":0,"class":2,"reason":"end","rule":null}]}
### idle then match
  req: {"op": "open", "flow": 0, "time": 0}
  -> : {"events":[]}
  req: {"op": "chunk", "packets": [{"flow": 0, "time": 9, "source": 0, "length": 10}]}
  -> : {"events":[{"type":"decision","flow":0,"class":7,"reason":"idle","at":0,"time":9,"rule":null},{"type":"match","flow":0,"rule":1,"start":0,"end":1}]}
  req: {"op": "close", "flow": 0, "time": 9}
  -> : {"events":[{"type":"closed","flow":0,"packets":1,"matches":1,"class":7,"reason":"idle","rule":null}]}
